CREATE TABLE "public"."modules" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "course_id"  bigint,
  "title"      text                     NOT NULL,
  "sort_order" integer                  NOT NULL,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  CONSTRAINT "modules_course_id_fkey" FOREIGN KEY (course_id) REFERENCES public.courses(id) ON DELETE CASCADE,
  CONSTRAINT "modules_pkey" PRIMARY KEY (id)
);

CREATE INDEX idx_modules_course_id ON public.modules USING btree (course_id);

CREATE TRIGGER set_timestamp_modules
  BEFORE UPDATE ON public.modules
  FOR EACH ROW
  EXECUTE FUNCTION public.update_timestamp();

REVOKE ALL ON SEQUENCE "public"."modules_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."modules_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."modules_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."modules_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."modules_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."modules_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."modules_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."modules_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."modules" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."modules" TO "service_role";

REVOKE ALL ON TABLE "public"."modules" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."modules" TO "postgres";
